// The Mexican Spanish (US market) bundle, loaded only by visitors in es-US (a separate
// chunk, see loadLocale in client/src/lib/i18n.ts).
//
// The copy itself is generated by scripts/l10n/assemble.mts into
// shared/l10n/es-US/{catalog,data,jsx}.ts; ../bundle.ts adds the derived and JSX twins.
// `lang` gives the client the Spanish intent, upsell and name handling.
import { ES_US } from "@shared/lang/es";
import { CATALOG } from "@shared/l10n/es-US/catalog";
import { DATA } from "@shared/l10n/es-US/data";
import { JSX_TEXT } from "@shared/l10n/es-US/jsx";
import { buildBundle } from "../bundle";

export default buildBundle({ catalog: CATALOG, data: DATA, jsx: JSX_TEXT, lang: ES_US });
